export function tokenize(text) {
  return text.match(/\s+|[^\s]+/g) ?? [];
}

export function diff(a, b) {
  const A = tokenize(a), B = tokenize(b);
  const ops = [];
  // common prefix
  let p = 0;
  while (p < A.length && p < B.length && A[p] === B[p]) p++;
  let sa = A.length, sb = B.length;
  while (sa > p && sb > p && A[sa-1] === B[sb-1]) { sa--; sb--; }
  if (p) ops.push({op:'eq', text: A.slice(0,p).join('')});
  // myers on A[p..sa) B[p..sb)
  const mid = myers(A, p, sa, B, p, sb); // array of [op, token]
  for (const [op, t] of mid) {
    const last = ops[ops.length-1];
    if (last && last.op === op) last.text += t;
    else ops.push({op, text: t});
  }
  if (sa < A.length) ops.push({op:'eq', text: A.slice(sa).join('')});
  return ops;
}
```

