```js
export function diff(a, b) {
  const A = tokenize(a);
  const B = tokenize(b);
  const ops = [];

  let pre = 0;
  const minLen = Math.min(A.length, B.length);
  while (pre < minLen && A[pre] === B[pre]) pre++;
  let ea = A.length, eb = B.length;
  while (ea > pre && eb > pre && A[ea - 1] === B[eb - 1]) { ea--; eb--; }

  if (pre > 0) pushOp(ops, 'eq', join(A, 0, pre));
  for (const [op, tok] of myers(A, pre, ea, B, pre, eb)) pushOp(ops, op, tok);
  if (ea < A.length) pushOp(ops, 'eq', join(A, ea, A.length));
  return ops;
}
```

