function myers(A, a0, a1, B, b0, b1) {
  const N = a1 - a0, M = b1 - b0;
  if (N <= 0) return M > 0 ? B.slice(b0, b1).map(t => ['ins', t]) : [];
  if (M <= 0) return A.slice(a0, a1).map(t => ['del', t]);

  const max = N + M;
  const trace = [new Int32Array(1)]; // d = 0
  let vPrev = trace[0];

  for (let d = 1; d <= max; d++) {
    const vCur = new Int32Array(d + 1);
    let done = false;
    for (let j = 0; j <= d; j++) {
      const k = -d + 2 * j;
      let x;
      if (k === -d) x = vPrev[j];
      else if (k === d) x = vPrev[j - 1] + 1;
      else if (vPrev[j - 1] < vPrev[j]) x = vPrev[j];
      else x = vPrev[j - 1] + 1;
      let y = x - k;
      while (x < N && y < M && A[a0 + x] === B[b0 + y]) { x++; y++; }
      vCur[j] = x;
      if (x >= N && y >= M) { done = true; break; }
    }
    trace.push(vCur);
    if (done) return backtrack(trace, A, a0, B, b0, N, M);
    vPrev = vCur;
  }
  return backtrack(trace, A, a0, B, b0, N, M); // unreachable
}
```

