import assert from 'node:assert/strict';
import { diff, toUnified } from '../worddiff.mjs';

const join = (ops) => ops.map((o) => o.text).join('');
const reconstructA = (ops) => ops.filter((o) => o.op !== 'ins').map((o) => o.text).join('');
const reconstructB = (ops) => ops.filter((o) => o.op !== 'del').map((o) => o.text).join('');

function mulberry32(seed) {
  let t = seed >>> 0;
  return function () {
    t += 0x6d2b79f5;
    let r = Math.imul(t ^ (t >>> 15), 1 | t);
    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
  };
}

test('empty vs non-empty', () => {
  assert.deepEqual(diff('', 'hello world'), [{ op: 'ins', text: 'hello world' }]);
  assert.deepEqual(diff('hello world', ''), [{ op: 'del', text: 'hello world' }]);
  assert.deepEqual(diff('', ''), []);
});

test('identical inputs collapse to a single eq run', () => {
  const ops = diff('the quick brown fox jumps', 'the quick brown fox jumps');
  assert.deepEqual(ops, [{ op: 'eq', text: 'the quick brown fox jumps' }]);
});

test('known small case: exact expected op list', () => {
  const ops = diff('the quick brown fox', 'the quick red fox');
  assert.deepEqual(ops, [
    { op: 'eq', text: 'the quick ' },
    { op: 'del', text: 'brown' },
    { op: 'ins', text: 'red' },
    { op: 'eq', text: ' fox' },
  ]);
  assert.equal(toUnified(ops), 'the quick [-brown-]{+red+} fox');
});

test('invariant: eq+del reconstructs a, eq+ins reconstructs b (50 random pairs)', () => {
  const rng = mulberry32(0xc0ffee);
  const VOCAB = ['alpha', 'beta', 'gamma', 'delta', 'epsilon', 'x', 'y', 'zeta', 'w', 'q'];
  const randDoc = () => {
    const n = 1 + Math.floor(rng() * 40);
    const words = Array.from({ length: n }, () => VOCAB[Math.floor(rng() * VOCAB.length)]);
    return words.join(rng() < 0.5 ? ' ' : '\n');
  };
  for (let i = 0; i < 50; i++) {
    const a = randDoc();
    const b = randDoc();
    const ops = diff(a, b);
    assert.equal(reconstructA(ops), a, `a reconstruction failed on pair ${i}`);
    assert.equal(reconstructB(ops), b, `b reconstruction failed on pair ${i}`);
    // no two adjacent runs share the same op type
    for (let j = 1; j < ops.length; j++) {
      assert.notEqual(ops[j].op, ops[j - 1].op, `unmerged adjacent runs in pair ${i}`);
